fn append(a: &Vec<i32>, b: i32) -> Vec<i32> {
    // Pre-allocate a new vector with capacity for all elements of `a` plus one more.
    let mut result = Vec::with_capacity(a.len() + 1);

    // Copy all elements from `a` into `result`, preserving order.
    result.extend_from_slice(a);

    // Append the new element at the end.
    result.push(b);

    result
}

